import unittest
from solution_stub import dedupe


class TestDedupe(unittest.TestCase):

    def test_empty_list(self):
        self.assertEqual(dedupe([]), [])

    def test_no_duplicates_preserves_order(self):
        self.assertEqual(dedupe([3, 1, 2]), [3, 1, 2])

    def test_all_duplicates(self):
        self.assertEqual(dedupe([5, 5, 5, 5]), [5])

    def test_basic_duplicates_order_preserved(self):
        self.assertEqual(dedupe([1, 2, 1, 3, 2, 4]), [1, 2, 3, 4])

    def test_interleaved_duplicates(self):
        self.assertEqual(
            dedupe([4, 3, 4, 2, 3, 1, 2, 5]),
            [4, 3, 2, 1, 5]
        )

    def test_strings(self):
        self.assertEqual(
            dedupe(["b", "a", "b", "c", "a"]),
            ["b", "a", "c"]
        )

    def test_single_element(self):
        self.assertEqual(dedupe([42]), [42])

    def test_negative_and_zero(self):
        self.assertEqual(dedupe([0, -1, 0, -1, -2]), [0, -1, -2])

    def test_mixed_types(self):
        # bool is subclass of int in Python, but here we test distinct hashable types
        self.assertEqual(
            dedupe([1, "1", 1, "1", 2.0, 2]),
            [1, "1", 2.0]
        )
        # Note: 2.0 == 2 in Python, so 2 is considered duplicate of 2.0

    def test_order_not_sorted(self):
        # Ensure output is NOT sorted, just first-occurrence order
        result = dedupe([10, 2, 33, 2, 10, 5])
        self.assertEqual(result, [10, 2, 33, 5])
        self.assertNotEqual(result, sorted(result))

    def test_does_not_mutate_input(self):
        original = [1, 2, 2, 3, 1]
        original_copy = list(original)
        dedupe(original)
        self.assertEqual(original, original_copy)

    def test_return_type_is_list(self):
        result = dedupe((1, 2, 2, 3))
        self.assertIsInstance(result, list)

    def test_large_input_order_preserved(self):
        items = list(range(1000)) + list(range(500))
        expected = list(range(1000))
        self.assertEqual(dedupe(items), expected)

    def test_tuples_as_items(self):
        items = [(1, 2), (3, 4), (1, 2), (5, 6)]
        self.assertEqual(dedupe(items), [(1, 2), (3, 4), (5, 6)])

    def test_none_values(self):
        items = [None, 1, None, 2]
        self.assertEqual(dedupe(items), [None, 1, 2])


if __name__ == "__main__":
    unittest.main()

