from solution_stub import fizzbuzz


class FizzBuzzTests(unittest.TestCase):

    def test_zero(self):
        self.assertEqual(fizzbuzz(0), [])

    def test_negative(self):
        self.assertEqual(fizzbuzz(-5), [])

    def test_one(self):
        self.assertEqual(fizzbuzz(1), ["1"])

    def test_three(self):
        self.assertEqual(fizzbuzz(3), ["1", "2", "Fizz"])

    def test_five(self):
        self.assertEqual(fizzbuzz(5), ["1", "2", "Fizz", "4", "Buzz"])

    def test_fifteen(self):
        expected = [
            "1", "2", "Fizz", "4", "Buzz", "Fizz", "7", "8", "Fizz", "Buzz",
            "11", "Fizz", "13", "14", "FizzBuzz"
        ]
        self.assertEqual(fizzbuzz(15), expected)

    def test_twenty(self):
        expected = [
            "1", "2", "Fizz", "4", "Buzz", "Fizz", "7", "8", "Fizz", "Buzz",
