import time


def retry(fn, attempts=3, base_delay=1.0, sleep=None):
    if sleep is None:
        sleep = time.sleep
    last_exception = None
    for n in range(1, attempts + 1):
        try:
            return fn()
        except Exception as exc:
            last_exception = exc
            if n < attempts:
                sleep(base_delay * 2 ** (n - 1))
    raise last_exception

