import re


def slugify(title):
    title = title.lower()
    # Treat runs of spaces, tabs, newlines, underscores, hyphens as one separator
    parts = re.split(r'[\s_\-]+', title)

    words = []
    for part in parts:
        # Drop every other non-alphanumeric character
        cleaned = re.sub(r'[^a-z0-9]', '', part)
        if cleaned:
            words.append(cleaned)

    if not words:
        return "untitled"

    return "-".join(words)

