tasks.finalCode:
def to_camel(s):
    parts = [p for p in s.split("_") if p]
    if not parts:
        return ""
    first = parts[0]
    rest = []
    for p in parts[1:]:
        rest.append(p[0].upper() + p[1:])
    return first + "".join(rest)

